// Package strip removes swag annotations and generated spec files from a
// working copy, so each run regenerates them from scratch and re-runs are
// idempotent.
package strip

import (
	"bytes"
	"fmt"
	"go/scanner"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// SpecDir is where swag writes the generated spec, relative to the repo root.
const SpecDir = "internal/apispec"

// generated lists the files swag writes into SpecDir. docs.go is removed only
// when it carries swag's "Code generated" header, so a hand-written file of
// that name survives.
var generated = []string{"swagger.json", "swagger.yaml", "docs.go"}

// Result says what Run removed.
type Result struct {
	Files   int      `json:"files"`   // .go files that lost lines
	Lines   int      `json:"lines"`   // annotation lines removed
	Deleted []string `json:"deleted"` // generated spec files deleted, slash paths
}

// Run strips annotation lines from the non-test .go files under dir, outside
// the directories skipDir names, and deletes the generated files in SpecDir.
// Those are the files patch_comment may write and commit may stage.
func Run(dir string) (Result, error) {
	res := Result{Deleted: []string{}}
	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if path != dir && skipDir(d.Name()) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		src, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out, n, err := Lines(filepath.Base(path), src)
		if err != nil || n == 0 {
			return err
		}
		res.Files++
		res.Lines += n
		return os.WriteFile(path, out, 0o644)
	})
	if err != nil {
		return res, err
	}
	for _, name := range generated {
		path := filepath.Join(dir, filepath.FromSlash(SpecDir), name)
		data, err := os.ReadFile(path)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return res, err
		}
		if name == "docs.go" && !bytes.Contains(data, []byte("Code generated by swaggo/swag")) {
			continue
		}
		if err := os.Remove(path); err != nil {
			return res, err
		}
		res.Deleted = append(res.Deleted, SpecDir+"/"+name)
	}
	// Leave no empty directory behind; Remove fails harmlessly if files remain.
	_ = os.Remove(filepath.Join(dir, filepath.FromSlash(SpecDir)))
	return res, nil
}

// swagAttrs are the attributes swag v1.16.6 reads, lowercased: it matches
// them case-insensitively.
var swagAttrs = map[string]bool{
	// operations
	"accept": true, "produce": true, "param": true, "success": true, "failure": true,
	"response": true, "header": true, "tags": true, "router": true, "deprecatedrouter": true,
	"summary": true, "description": true, "description.markdown": true, "id": true,
	"deprecated": true, "security": true, "state": true,
	// general API info
	"title": true, "version": true, "termsofservice": true, "host": true, "hoststate": true,
	"basepath": true, "schemes": true, "query.collection.format": true,
	// inside a security definition
	"in": true, "name": true, "tokenurl": true, "authorizationurl": true,
}

// swagFamilies start attribute names swag reads as a family, such as
// @contact.email, @tag.name, @securityDefinitions.apikey or @x-logo.
var swagFamilies = []string{"x-", "tag.", "contact.", "license.", "externaldocs.", "securitydefinitions.", "scope."}

// IsAnnotation reports whether a line comment's text is a swag annotation:
// "// @Attr…" or "//@Attr…" with an attribute swag reads. Other "// @"
// comments, such as "// @see" or "// @todo", belong to the code's authors.
func IsAnnotation(comment string) bool {
	text, ok := strings.CutPrefix(comment, "// @")
	if !ok {
		if text, ok = strings.CutPrefix(comment, "//@"); !ok {
			return false
		}
	}
	attr, _, _ := strings.Cut(strings.ToLower(text), " ")
	attr, _, _ = strings.Cut(attr, "\t")
	if swagAttrs[attr] {
		return true
	}
	for _, f := range swagFamilies {
		if strings.HasPrefix(attr, f) && len(attr) > len(f) {
			return true
		}
	}
	return false
}

// skipDir reports whether Run leaves a directory alone: .git and the
// directories the go tool ignores (vendor, testdata, ".x", "_x"), which swag
// does not read and a run must not change.
func skipDir(name string) bool {
	return name == "vendor" || name == "testdata" || strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_")
}

// Lines returns src without its annotation lines, and how many it removed.
// An annotation line holds only a "// @" line comment and whitespace; a
// trailing comment after code is kept, and text inside string literals or
// block comments is never touched because the source is tokenized, not
// matched line by line.
func Lines(name string, src []byte) ([]byte, int, error) {
	fset := token.NewFileSet()
	file := fset.AddFile(name, -1, len(src))
	var errs scanner.ErrorList
	var s scanner.Scanner
	s.Init(file, src, func(pos token.Position, msg string) { errs.Add(pos, msg) }, scanner.ScanComments)

	var out bytes.Buffer
	last, n := 0, 0 // src[last:] is not yet copied
	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		if tok != token.COMMENT || !IsAnnotation(lit) {
			continue
		}
		off := file.Offset(pos)
		start := bytes.LastIndexByte(src[:off], '\n') + 1
		if len(bytes.TrimSpace(src[start:off])) > 0 {
			continue // code before the comment on the same line
		}
		end := len(src)
		if i := bytes.IndexByte(src[off:], '\n'); i >= 0 {
			end = off + i + 1
		}
		out.Write(src[last:start])
		last = end
		n++
	}
	if errs.Len() > 0 {
		return nil, 0, fmt.Errorf("scan %s: %w", name, errs.Err())
	}
	out.Write(src[last:])
	return out.Bytes(), n, nil
}
